1909	  const isPresent = key in input;
1910	  const isOptionalOut = optout === "optional";
1911	  // The middle rung means "absence permitted, nothing supplied in its place", so an absent key contributes nothing — whatever the schema made of `undefined` is invented, not substituted. Only `optional` reaches this with a value: `defaulted` substitutes, and a schema that isn't optional-out has to keep the key.
1912	  if (!isPresent && isOptionalOut && optin === "optional") {
1913	    return;
1914	  }
1915	  if (result.issues.length) {
1916	    // For optional-in/out schemas, ignore errors on absent keys.
1917	    if (optin !== undefined && isOptionalOut && !isPresent) {
1918	      return;
